11	  isOpen: boolean;
12	  /**
13	   * Fires on every close path — backdrop click, close X, Esc (all three arrive via
14	   * `ZimmDrawer`'s own `onClose`, wired straight to this) — **and** the "stay" CTA's own
15	   * `onClick`. Always a direct, synchronous call from the interaction handler, never deferred to
16	   * `ZimmDrawer`'s `onCloseComplete`/exit-animation callback: the consumer writes a suppression
17	   * cookie inside `onDismiss` before performing a hard `window.location =` navigation elsewhere
18	   * in the flow, and a deferred callback risks losing that write to a fast subsequent page unload.
19	   */
20	  onDismiss: () => void;
21	};
