1	import React, { useEffect, useState } from 'react';
2	import { ZimmCountryLanguageMismatch } from 'app/components/ui-kits/organisms/zimmCountryLanguageMismatch';
3	import { getRegionPrefCookie, setRegionPrefCookie } from 'app/utils/regionPrefCookie';
4	import { shouldShowLanguagePrompt } from 'app/utils/shouldShowLanguagePrompt';
5	import { crossSiteUrl } from 'app/utils/crossSiteUrl';
6	import type { BuildCrossSiteUrl } from 'app/utils/crossSiteUrl';
7	
8	/**
9	 * Matches the real shape `useMultiSite()` returns (see
10	 * `node_modules/@salesforce/retail-react-app/app/hooks/use-multi-site.js`) — declared locally
11	 * rather than imported, the same technique `useCountryConfig.ts`'s own local `MultiSiteContext`
12	 * type already uses, since `useMultiSite` itself ships untyped.
13	 */
14	export type ZimmLanguagePromptProps = {
15	  /** The runtime's current PWA site, exactly as `_app` already has it from `useMultiSite()`. */
16	  site: { id: string; sfccSiteId?: string };
17	  /** The runtime's current locale, exactly as `_app` already has it from `useMultiSite()`. */
18	  locale: { id: string };
19	  /** The real `buildUrl` from `useMultiSite()`, forwarded straight through to `crossSiteUrl`. */
20	  buildUrl: BuildCrossSiteUrl;
21	};
22	
23	type EuLanguageConfigEntry = {
24	  /** The target PWA site's URL alias — see `config/sites.overlay.js`. */
25	  readonly alias: string;
26	  /** The target PWA site's own locale id — see `config/sites.overlay.js`. */
27	  readonly locale: string;
28	  /** Phrase-carrying value for the `{inCountry}` copy token (decisions.md's "phrase-carrying
29	   *  tokens, not bare nouns" note) — always includes its own preposition. */
30	  readonly countryPhrase: string;
31	  /** Phrase-carrying value for the `{inLanguage}`/`{inCurrentLanguage}` copy tokens. */
32	  readonly languagePhrase: string;
33	};
34	
35	/**
36	 * Deliberate, temporary stand-in for real geo-detection (SFCC-817/823) — a fixed language code ->
37	 * target-site/display map. Approved by Marcel after a live Storybook review of all four cases
38	 * (see `zimmCountryLanguageMismatch/index.stories.tsx`'s `LanguageDetected*` stories, hand-typed
39	 * to match this map's real output so a drift between the two shows up as a visible story
40	 * regression, not a silent divergence).
41	 *
42	 * `en` reads "in Ireland", not "the UK": Zimmermann already has a separate, real UK storefront
43	 * (`ZimmermannUK`, `/uk/`) that this EU-English site is NOT, so naming the UK here would
44	 * contradict the site's own architecture, not just be geographically approximate — see this exact
45	 * reasoning recorded in `zimmCountryLanguageMismatch/index.stories.tsx`'s `LanguageDetectedEnglish`
46	 * story comment, which this map's `en` entry was built to match.
47	 *
48	 * `alias`/`locale` verified against `config/sites.overlay.js:39-42`; `countryPhrase`/
49	 * `languagePhrase` have no config source — they're this feature's own copy. Kept as one combined
50	 * map (not two that could drift apart) — see this file's own test for the guard that its keys
51	 * stay identical to `shouldShowLanguagePrompt.ts`'s `SUPPORTED_EU_LANGUAGES`.
52	 */
53	export const EU_LANGUAGE_CONFIG: Record<string, EuLanguageConfigEntry> = {
54	  en: { alias: 'en-eu', locale: 'en-GB', countryPhrase: 'in Ireland', languagePhrase: 'in English' },
55	  fr: { alias: 'fr-eu', locale: 'fr', countryPhrase: 'in France', languagePhrase: 'in French' },
56	  it: { alias: 'it-eu', locale: 'it', countryPhrase: 'in Italy', languagePhrase: 'in Italian' },
57	  es: { alias: 'es-eu', locale: 'es', countryPhrase: 'in Spain', languagePhrase: 'in Spanish' },
58	};
59	
60	type LanguagePromptState = {
61	  isOpen: boolean;
62	  targetLanguage: string;
63	};
64	
65	const CLOSED_STATE: LanguagePromptState = { isOpen: false, targetLanguage: '' };
66	
67	/**
68	 * Writes the language-prompt suppression timestamp into the shared `zimm-region-pref` cookie,
69	 * spreading the existing value first — `regionPrefCookie.ts`'s `setRegionPrefCookie` replaces the
70	 * whole cookie value (there is no partial-update form), so skipping the spread would silently
71	 * erase a sibling flag. Confirmed by grep as of this step: `countrySuppressedAt` (the future
72	 * country-mismatch prompt's own flag, `regionPrefCookie.ts:55`) has no production caller
73	 * anywhere in this codebase yet — only its type/parse/serialise plumbing exists — so this spread
74	 * is the only thing standing between a future SFCC-823 write and this container silently
75	 * clobbering it.
76	 */
77	const suppressLanguagePrompt = (): void => {
78	  setRegionPrefCookie({ ...getRegionPrefCookie(), languageSuppressedAt: Math.floor(Date.now() / 1000) });
79	};
80	
81	/**
82	 * Organism (container) — mounts the EU-domestic language-mismatch prompt (SFCC-689) in `_app`.
83	 * On mount only, reads `navigator.languages` and the suppression cookie, asks
84	 * `shouldShowLanguagePrompt` whether to show, and if so renders `ZimmCountryLanguageMismatch`
85	 * (`variant="language"`); otherwise renders nothing.
86	 *
87	 * **Takes `site`/`locale`/`buildUrl` as props, not its own `useMultiSite()` call.**
88	 * `components.md`'s container/presentational rule allows only `useIntl`/`useUiCopy` as hook
89	 * exceptions inside `components/` — every other data-fetching hook belongs in a page or another
90	 * container. `_app` already destructures all three from `useMultiSite()` for its own use, so
91	 * threading them through as props here keeps this container prop-driven and keeps the `_app`
92	 * mount to a single JSX line.
93	 *
94	 * **Cookie write, then hard navigation — always in that order, always synchronous.**
95	 * `window.location.href =` unloads the page; a write issued after navigation starts (or an async
96	 * write) may never land, and the shopper would see the prompt again next visit despite having
97	 * just acted on it. This is also why switching site is a hard navigation rather than a
98	 * client-side route change: an EU-domestic site switch changes the Commerce API `siteId`, basket
99	 * context and locale, all resolved from the URL at boot — a route change would update the address
100	 * bar and leave the app running against the old site's API.
101	 */
102	export const ZimmLanguagePrompt = ({ site, locale, buildUrl }: ZimmLanguagePromptProps) => {
103	  const [languagePromptState, setLanguagePromptState] = useState<LanguagePromptState>(CLOSED_STATE);
104	
105	  // Runs once per mount: browser language and the suppression cookie are both read exactly once.
106	  // Nothing here needs to react to a later site/locale prop change within the same page life — an
107	  // EU-domestic site switch is always the hard navigation described above, never an in-place
108	  // update this effect would need to respond to.
109	  useEffect(() => {
110	    const result = shouldShowLanguagePrompt({
111	      sfccSiteId: site.sfccSiteId,
112	      currentLanguage: locale.id,
113	      browserLanguages: navigator.languages,
114	      suppressedAt: getRegionPrefCookie().languageSuppressedAt,
115	      now: Math.floor(Date.now() / 1000),
116	    });
117	
118	    if (result.show) {
119	      setLanguagePromptState({ isOpen: true, targetLanguage: result.targetLanguage });
120	    }
121	  }, []);
122	
123	  const handleDismiss = (): void => {
124	    suppressLanguagePrompt();
125	    setLanguagePromptState(CLOSED_STATE);
126	  };
127	
128	  const handleSwitchLanguage = (target: unknown): void => {
129	    if (typeof target !== 'string') return;
130	    const config = EU_LANGUAGE_CONFIG[target];
131	    if (!config) return;
132	
133	    // Cookie write first, then navigate — both synchronous, no await between them. See this
134	    // component's own doc comment for why the ordering is load-bearing, not stylistic.
135	    suppressLanguagePrompt();
136	    window.location.href = crossSiteUrl(config.alias, config.locale, buildUrl);
137	  };
138	
139	  if (!languagePromptState.isOpen) {
140	    return null;
141	  }
142	
143	  const targetConfig = EU_LANGUAGE_CONFIG[languagePromptState.targetLanguage];
144	  if (!targetConfig) {
145	    return null;
146	  }
147	  const currentConfig = Object.values(EU_LANGUAGE_CONFIG).find((entry) => entry.locale === locale.id);
148	
149	  return (
150	    <ZimmCountryLanguageMismatch
151	      variant="language"
152	      isOpen={languagePromptState.isOpen}
153	      onDismiss={handleDismiss}
154	      inCountry={targetConfig.countryPhrase}
155	      inLanguage={targetConfig.languagePhrase}
156	      inCurrentLanguage={currentConfig?.languagePhrase ?? ''}
157	      target={languagePromptState.targetLanguage}
158	      onSwitchLanguage={handleSwitchLanguage}
159	    />
160	  );
161	};
162	
163	export default ZimmLanguagePrompt;
164

