import React from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { ZimmLanguagePrompt } from './index';
import { COOKIE_NAME, setRegionPrefCookie } from 'app/utils/regionPrefCookie';

const meta: Meta<typeof ZimmLanguagePrompt> = {
  title: 'Layout/ZimmLanguagePrompt',
  component: ZimmLanguagePrompt,
};
export default meta;
type Story = StoryObj<typeof ZimmLanguagePrompt>;

// Two thin stories, no `play` — the interaction/callback-wiring assertions this would otherwise
// exercise already live, more precisely, in this component's own index.test.tsx (mocked
// navigator/cookie, ordering asserted via mock.invocationCallOrder) and in
// zimmCountryLanguageMismatch/index.test.tsx (per .claude/rules/testing.md's "do not duplicate
// coverage across layers" note).
//
// Both real signals this component reads on mount — `navigator.languages` and the
// `zimm-region-pref` cookie — are deliberately NOT props (see index.tsx's own doc comment: this
// container takes only `{site, locale, buildUrl}`, matching what `_app` already has in scope), so
// they can't be seeded via a Storybook arg the normal way. Each story below sets both directly,
// synchronously, in its own wrapper component's *render body* — not inside a `useEffect`. React
// flushes a newly-mounted tree's effects bottom-up (children before parents), so a wrapper-level
// `useEffect` would run *after* ZimmLanguagePrompt's own eligibility-check effect has already read
// whatever value was there beforehand. Setting both during render guarantees they're in place
// before anything in the tree mounts.

const SITE = { id: 'ZimmermannEUit', sfccSiteId: 'ZimmermannEU' };
const LOCALE = { id: 'it' };
const BUILD_URL = (path: string): string => path;

/**
 * Overrides `navigator.languages` by defining a fresh own-property directly on the `navigator`
 * instance, shadowing `Navigator.prototype`'s own getter — the standard technique for overriding
 * `navigator.*` in a real browser context (used the same way by browser automation tools). This
 * does not require the prototype's own accessor to be configurable, since it adds a new property
 * on the instance rather than redefining the prototype's.
 */
const setBrowserLanguages = (languages: readonly string[]): void => {
  Object.defineProperty(window.navigator, 'languages', {
    value: languages,
    configurable: true,
  });
};

/** Clears the cookie directly — `regionPrefCookie.ts`'s `setRegionPrefCookie(value)` serialises
 *  and writes exactly the object it's given (`regionPrefCookie.ts:122-125`), with no merge/clear
 *  form, so there is no exported helper to reach for here. An expired `max-age=0` removes the
 *  cookie outright. */
const clearRegionPrefCookie = (): void => {
  document.cookie = `${COOKIE_NAME}=; path=/; max-age=0`;
};

const EligibleExample = () => {
  clearRegionPrefCookie();
  setBrowserLanguages(['fr-FR']);
  return <ZimmLanguagePrompt site={SITE} locale={LOCALE} buildUrl={BUILD_URL} />;
};

/** A shopper on `/it-eu/` (Italian storefront) whose browser reports French — matches the build
 *  plan's own worked example. Nothing suppresses the prompt, so it opens on mount. */
export const Eligible: Story = {
  render: () => <EligibleExample />,
};

const SuppressedExample = () => {
  setRegionPrefCookie({ languageSuppressedAt: Math.floor(Date.now() / 1000) });
  setBrowserLanguages(['fr-FR']);
  return <ZimmLanguagePrompt site={SITE} locale={LOCALE} buildUrl={BUILD_URL} />;
};

/** Same mismatch as `Eligible`, but the shopper already dismissed/acted on the prompt within the
 *  last `LANGUAGE_PROMPT_SUPPRESSION_DAYS` window — renders nothing. */
export const Suppressed: Story = {
  render: () => <SuppressedExample />,
};

