'use strict';

const { chromium } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright');

const BASE_URL = 'http://localhost:6006';

const STORIES = [
  {
    key: 'eligible',
    id: 'layout-zimmlanguageprompt--eligible',
    screenshotPath: '/tmp/zimm-language-prompt-eligible.png',
    expectRendered: true,
    expected: {
      heading: 'Welcome to Zimmermann Europe',
      body: "Welcome to Zimmermann Europe. We noticed you're in France, would you like to view our site in French?",
      switchCta: 'View in French',
      stayCta: 'Continue in Italian',
    },
  },
  {
    key: 'suppressed',
    id: 'layout-zimmlanguageprompt--suppressed',
    screenshotPath: '/tmp/zimm-language-prompt-suppressed.png',
    expectRendered: false,
  },
  {
    key: 'language-detected-italian',
    id: 'layout-zimmcountrylanguagemismatch--language-detected-italian',
    screenshotPath: '/tmp/zimm-language-detected-italian.png',
    expectRendered: true,
    expected: {
      heading: 'Welcome to Zimmermann Europe',
      body: "Welcome to Zimmermann Europe. We noticed you're in Italy, would you like to view our site in Italian?",
      switchCta: 'View in Italian',
      stayCta: 'Continue in English',
    },
  },
  {
    key: 'language-detected-spanish',
    id: 'layout-zimmcountrylanguagemismatch--language-detected-spanish',
    screenshotPath: '/tmp/zimm-language-detected-spanish.png',
    expectRendered: true,
    expected: {
      heading: 'Welcome to Zimmermann Europe',
      body: "Welcome to Zimmermann Europe. We noticed you're in Spain, would you like to view our site in Spanish?",
      switchCta: 'View in Spanish',
      stayCta: 'Continue in English',
    },
  },
  {
    key: 'language-detected-english',
    id: 'layout-zimmcountrylanguagemismatch--language-detected-english',
    screenshotPath: '/tmp/zimm-language-detected-english.png',
    expectRendered: true,
    expected: {
      heading: 'Welcome to Zimmermann Europe',
      body: "Welcome to Zimmermann Europe. We noticed you're in Ireland, would you like to view our site in English?",
      switchCta: 'View in English',
      stayCta: 'Continue in French',
    },
  },
];

function log(section, msg) {
  console.log(`[${section}] ${msg}`);
}

async function runStory(browser, story) {
  const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
  const page = await context.newPage();

  const consoleMessages = [];
  const pageErrors = [];
  const requestFailures = [];

  page.on('console', (msg) => {
    consoleMessages.push({ type: msg.type(), text: msg.text() });
  });
  page.on('pageerror', (err) => {
    pageErrors.push(err && err.message ? err.message : String(err));
  });
  page.on('requestfailed', (req) => {
    const failure = req.failure();
    requestFailures.push(`${req.url()} :: ${failure ? failure.errorText : 'unknown'}`);
  });

  const url = `${BASE_URL}/iframe.html?id=${story.id}&viewMode=story`;
  let navError = null;

  try {
    await page.goto(url, { waitUntil: 'load', timeout: 30000 });
  } catch (e) {
    navError = e.message;
  }

  // Best-effort extra settle for networkidle. NOT used as the primary wait condition:
  // Storybook's dev server keeps an HMR websocket open, which can prevent "networkidle"
  // from ever being reached and would otherwise turn into a false 30s navigation timeout.
  // Capped short and non-fatal.
  await page.waitForLoadState('networkidle', { timeout: 5000 }).catch(() => {});

  // Fixed settle buffer for the mount-time useEffect (cookie/navigator.languages read) and
  // ZimmDrawer's 300ms framer-motion enter transition to finish.
  await page.waitForTimeout(1200);

  let headingVisible = false;
  try {
    await page.getByRole('heading', { level: 2 }).first().waitFor({ state: 'visible', timeout: 3000 });
    headingVisible = true;
  } catch (e) {
    headingVisible = false;
  }

  let dialogRoleCount = 0;
  try {
    dialogRoleCount = await page.getByRole('dialog').count();
  } catch (e) {
    dialogRoleCount = -1;
  }

  let headingText = null;
  let bodyText = null;
  const buttons = [];

  if (headingVisible) {
    headingText = await page.getByRole('heading', { level: 2 }).first().textContent().catch(() => null);
    bodyText = await page.locator('p').first().textContent().catch(() => null);

    const buttonLocators = await page.getByRole('button').all();
    for (const btn of buttonLocators) {
      const ariaLabel = await btn.getAttribute('aria-label').catch(() => null);
      const textContent = await btn.textContent().catch(() => null);
      const innerText = await btn.innerText().catch(() => null);
      buttons.push({ ariaLabel, textContent, innerText });
    }
  }

  const bodyInnerText = await page
    .locator('body')
    .innerText()
    .catch((e) => `<<ERROR: ${e.message}>>`);
  const bodyInnerHTML = await page
    .locator('body')
    .innerHTML()
    .catch((e) => `<<ERROR: ${e.message}>>`);

  await page.screenshot({ path: story.screenshotPath, fullPage: true }).catch((e) => {
    log(story.key, `SCREENSHOT ERROR: ${e.message}`);
  });

  await context.close();

  return {
    key: story.key,
    id: story.id,
    url,
    navError,
    headingVisible,
    dialogRoleCount,
    headingText,
    bodyText,
    buttons,
    bodyInnerText,
    bodyInnerHTMLLength: typeof bodyInnerHTML === 'string' ? bodyInnerHTML.length : null,
    consoleMessages,
    pageErrors,
    requestFailures,
    screenshotPath: story.screenshotPath,
    expected: story.expected || null,
    expectRendered: story.expectRendered,
  };
}

(async () => {
  let browser;
  try {
    browser = await chromium.launch({ headless: true });
  } catch (e) {
    console.error('FATAL: failed to launch headless chromium.');
    console.error(e && e.stack ? e.stack : String(e));
    process.exitCode = 1;
    return;
  }

  console.log(`Playwright chromium launched. Version: ${browser.version()}`);

  const results = [];
  for (const story of STORIES) {
    log(story.key, `Navigating to ${BASE_URL}/iframe.html?id=${story.id}&viewMode=story`);
    try {
      const result = await runStory(browser, story);
      results.push(result);

      log(story.key, `navError=${result.navError}`);
      log(story.key, `headingVisible=${result.headingVisible} dialogRoleCount=${result.dialogRoleCount}`);
      log(story.key, `headingText=${JSON.stringify(result.headingText)}`);
      log(story.key, `bodyText=${JSON.stringify(result.bodyText)}`);
      log(story.key, `buttons=${JSON.stringify(result.buttons)}`);
      log(story.key, `bodyInnerText=${JSON.stringify(result.bodyInnerText)}`);
      log(story.key, `bodyInnerHTMLLength=${result.bodyInnerHTMLLength}`);
      log(
        story.key,
        `consoleMessages(count=${result.consoleMessages.length})=${JSON.stringify(result.consoleMessages)}`,
      );
      log(story.key, `pageErrors(count=${result.pageErrors.length})=${JSON.stringify(result.pageErrors)}`);
      log(
        story.key,
        `requestFailures(count=${result.requestFailures.length})=${JSON.stringify(result.requestFailures)}`,
      );
      log(story.key, `screenshot saved: ${result.screenshotPath}`);
    } catch (e) {
      console.error(`[${story.key}] FATAL ERROR running story: ${e && e.stack ? e.stack : String(e)}`);
      results.push({ key: story.key, id: story.id, fatalError: e.message });
    }
    console.log('---');
  }

  await browser.close();

  console.log('=== RAW JSON RESULTS ===');
  console.log(JSON.stringify(results, null, 2));
})();

