    console.error(e && e.stack ? e.stack : String(e));
    process.exitCode = 1;
    return;
  }

  console.log(`Playwright chromium launched. Version: ${browser.version()}`);

  const results = [];
  for (const story of STORIES) {
    log(story.key, `Navigating to ${BASE_URL}/iframe.html?id=${story.id}&viewMode=story`);
    try {
      const result = await runStory(browser, story);
      results.push(result);

      log(story.key, `navError=${result.navError}`);
      log(story.key, `headingVisible=${result.headingVisible} dialogRoleCount=${result.dialogRoleCount}`);
      log(story.key, `headingText=${JSON.stringify(result.headingText)}`);
      log(story.key, `bodyText=${JSON.stringify(result.bodyText)}`);
      log(story.key, `buttons=${JSON.stringify(result.buttons)}`);
      log(story.key, `bodyInnerText=${JSON.stringify(result.bodyInnerText)}`);
      log(story.key, `bodyInnerHTMLLength=${result.bodyInnerHTMLLength}`);
      log(
        story.key,
        `consoleMessages(count=${result.consoleMessages.length})=${JSON.stringify(result.consoleMessages)}`,
      );
      log(story.key, `pageErrors(count=${result.pageErrors.length})=${JSON.stringify(result.pageErrors)}`);
      log(
        story.key,
        `requestFailures(count=${result.requestFailures.length})=${JSON.stringify(result.requestFailures)}`,
      );
      log(story.key, `screenshot saved: ${result.screenshotPath}`);
    } catch (e) {
      console.error(`[${story.key}] FATAL ERROR running story: ${e && e.stack ? e.stack : String(e)}`);
      results.push({ key: story.key, id: story.id, fatalError: e.message });
    }
    console.log('---');
  }

  await browser.close();

  console.log('=== RAW JSON RESULTS ===');
  console.log(JSON.stringify(results, null, 2));
})();

